from typing import Dict, List, TypedDict, Optional
import time
from typing import Dict
from typing import List, Dict



class TaskInfo(TypedDict):
    task_id: str
    description: str
    status: str  # Must be one of: "pending", "in progress", "completed", "blocked"
    created_at: float  # Unix timestamp
    completed_at: Optional[float]  # Unix timestamp, set when completed
    due_date: Optional[float]
    priority: str
    assigned_to: Optional[str]  # user_id

class UserInfo(TypedDict):
    _id: str
    name: str
    role: str  # Corrected from 'rol'

class ProjectInfo(TypedDict):
    project_id: str
    name: str
    start_date: float
    end_date: Optional[float]
    tasks: List[str]  # List of task_ids

class TaskTrackingSystem:
    def __init__(self):
        """
        A task tracking system to manage tasks, users, and projects.
        """
        # Tasks: {task_id: TaskInfo}
        self.tasks: Dict[str, TaskInfo] = {}

        # Users: {user_id: UserInfo}
        self.users: Dict[str, UserInfo] = {}

        # Projects: {project_id: ProjectInfo}
        self.projects: Dict[str, ProjectInfo] = {}

        # Constraints reminder:
        # - A task can only be marked as "completed" if its current status is not already "completed"
        # - The completed_at timestamp must be set when a task's status is updated to "completed"
        # - The status field must be one of: "pending", "in progress", "completed", "blocked"
        # - Task IDs must be unique within the system

    def get_task_by_id(self, task_id: str) -> dict:
        """
        Retrieve full details of a task given its unique task ID.

        Args:
            task_id (str): The unique identifier of the task.

        Returns:
            dict: {
                "success": True,
                "data": TaskInfo  # Full task information
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Task not found"
            }

        Constraints:
            - The task_id must exist in the system.
            - Task IDs are unique; only one task will match.
        """
        if not task_id:
            return { "success": False, "error": "Task ID cannot be empty" }

        task = self.tasks.get(task_id)
        if task is None:
            return { "success": False, "error": "Task not found" }

        return { "success": True, "data": task }

    def list_all_tasks(self) -> dict:
        """
        Retrieve all tasks in the system.

        Returns:
            dict: {
                "success": True,
                "data": List[TaskInfo]  # List of all tasks; empty list if no tasks exist
            }

        Constraints:
            - None (read-only operation).
            - All tasks returned are guaranteed to have valid structure per TaskInfo.
        """
        try:
            # Return a list of all task values
            all_tasks = list(self.tasks.values())
            return { "success": True, "data": all_tasks }
        except Exception as e:
            # Though unlikely, catch any unexpected error and return safe failure
            return { "success": False, "error": f"Failed to retrieve tasks: {str(e)}" }

    def list_tasks_by_status(self, status: str) -> dict:
        """
        Retrieve all tasks filtered by a specific status.

        Args:
            status (str): The status to filter by. Must be one of: "pending", "in progress", "completed", "blocked".

        Returns:
            dict: {
                "success": True,
                "data": List[TaskInfo]  # List of tasks with the specified status (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Invalid status value"
            }

        Constraints:
            - The status must be one of the allowed values: "pending", "in progress", "completed", "blocked".
        """
        allowed_statuses = ["pending", "in progress", "completed", "blocked"]

        if status not in allowed_statuses:
            return { "success": False, "error": "Invalid status value" }

        result = [
            task_info for task_info in self.tasks.values()
            if task_info["status"] == status
        ]

        return { "success": True, "data": result }

    def list_tasks_by_user(self, user_id: str) -> dict:
        """
        Retrieve all tasks assigned to a specific user.

        Args:
            user_id (str): The unique identifier of the user.

        Returns:
            dict: {
                "success": True,
                "data": List[TaskInfo]  # List of tasks assigned to the user (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "User does not exist"
            }

        Constraints:
            - The user_id must correspond to an existing user.
            - Only tasks where 'assigned_to' matches the user_id are returned.
        """
        if user_id not in self.users:
            return {"success": False, "error": "User does not exist"}

        assigned_tasks = [
            task_info for task_info in self.tasks.values()
            if task_info["assigned_to"] == user_id
        ]

        return {"success": True, "data": assigned_tasks}

    def list_tasks_in_project(self, project_id: str) -> dict:
        """
        Retrieve all tasks associated with the given project_id.

        Args:
            project_id (str): The unique identifier of the project.

        Returns:
            dict: {
                "success": True,
                "data": List[TaskInfo]  # List of task details for tasks in the project; may be empty
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Project not found"
            }

        Constraints:
            - The project_id must exist in the system.
            - Only tasks that exist in the system are included in the result.
        """
        project = self.projects.get(project_id)
        if not project:
            return {"success": False, "error": "Project not found"}

        task_ids = project["tasks"]
        tasks_in_project = []
        for task_id in task_ids:
            if task_id in self.tasks:
                tasks_in_project.append(self.tasks[task_id])

        return {"success": True, "data": tasks_in_project}

    def get_task_status(self, task_id: str) -> dict:
        """
        Retrieve the current status of a task by its ID, without returning full task details.

        Args:
            task_id (str): The unique identifier of the task.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "status": str  # One of: "pending", "in progress", "completed", "blocked"
                }
            }
            or
            {
                "success": False,
                "error": "Task not found"
            }

        Constraints:
            - The task_id must exist in the system.
        """
        task = self.tasks.get(task_id)
        if not task:
            return {"success": False, "error": "Task not found"}

        return {"success": True, "data": {"status": task["status"]}}

    def get_user_by_id(self, user_id: str) -> dict:
        """
        Retrieve user information by user_id.

        Args:
            user_id (str): The unique identifier of the user.

        Returns:
            dict: {
                "success": True,
                "data": UserInfo  # The user's information
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., "User not found"
            }

        Constraints:
            - The user_id must exist in the system.
        """
        if not user_id:
            return { "success": False, "error": "User ID cannot be empty" }

        user = self.users.get(user_id)
        if user is None:
            return { "success": False, "error": "User not found" }

        return { "success": True, "data": user }

    def get_project_by_id(self, project_id: str) -> dict:
        """
        Retrieve project details by its project_id.

        Args:
            project_id (str): The unique identifier of the project.

        Returns:
            dict: {
                "success": True,
                "data": ProjectInfo
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Project not found"
            }

        Constraints:
            - The project_id must exist in the system.
        """
        project = self.projects.get(project_id)
        if not project:
            return { "success": False, "error": "Project not found" }

        return { "success": True, "data": project }

    def get_incomplete_tasks(self) -> dict:
        """
        Retrieve all tasks that are not in "completed" status.

        Returns:
            dict: {
                "success": True,
                "data": List[TaskInfo]  # List of tasks where status != "completed"
            }

        Note:
            - The status field is expected to be one of: "pending", "in progress", "completed", "blocked".
            - Only tasks with status not equal to "completed" are included.
            - The result may be an empty list if no incomplete tasks exist.
        """
        incomplete_tasks = [
            task_info for task_info in self.tasks.values()
            if task_info["status"] != "completed"
        ]
        return {"success": True, "data": incomplete_tasks}

    def is_task_completable(self, task_id: str) -> dict:
        """
        Check whether a task can be marked as completed (i.e., its status is not already "completed").

        Args:
            task_id (str): The unique identifier of the task.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "completable": bool  # True if task exists and is not already completed
                }
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g. "Task not found"
            }

        Constraints:
            - Only tasks with a status other than "completed" are completable.
            - The task must exist in the system.
        """
        if task_id not in self.tasks:
            return { "success": False, "error": "Task not found" }

        task = self.tasks[task_id]
        completable = task["status"] != "completed"

        return { "success": True, "data": { "completable": completable } }


    def complete_task(self, task_id: str) -> dict:
        """
        Mark a task as "completed", set the completed_at timestamp, and enforce status constraints.

        Args:
            task_id (str): The unique identifier of the task to complete.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success: confirmation message
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - The task must exist.
            - The task's status must not already be "completed".
            - The completed_at timestamp is set automatically upon completion.
            - Status must be one of: "pending", "in progress", "completed", "blocked".
        """
        if task_id not in self.tasks:
            return { "success": False, "error": f"Task '{task_id}' does not exist" }

        task = self.tasks[task_id]

        if task["status"] == "completed":
            return { "success": False, "error": f"Task '{task_id}' is already completed" }

        # Valid status transition: not yet completed → completed
        task["status"] = "completed"
        current_time = time.time()
        task["completed_at"] = current_time

        return { "success": True, "message": f"Task '{task_id}' marked as completed." }


    def update_task_status(self, task_id: str, new_status: str) -> Dict[str, object]:
        """
        Change the status of a task to a valid value.

        Args:
            task_id (str): The unique ID of the task to update.
            new_status (str): The new status to set. Must be one of:
                             "pending", "in progress", "completed", "blocked".

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # On failure
            }

        Constraints:
            - Task must exist.
            - New status must be one of the allowed values.
            - A task already marked "completed" cannot be completed again.
            - If status is set to "completed", the completed_at timestamp is set to current time.
        """
        # Check if task exists
        if task_id not in self.tasks:
            return { "success": False, "error": f"Task with ID '{task_id}' not found." }

        allowed_statuses = ["pending", "in progress", "completed", "blocked"]
        if new_status not in allowed_statuses:
            return {
                "success": False,
                "error": f"Invalid status '{new_status}'. Must be one of {allowed_statuses}."
            }

        task = self.tasks[task_id]

        # Prevent re-completing a completed task
        if new_status == "completed":
            if task["status"] == "completed":
                return {
                    "success": False,
                    "error": "Task is already completed and cannot be completed again."
                }
            # Set completed_at timestamp
            task["completed_at"] = time.time()

        # Update the status
        task["status"] = new_status

        return { "success": True, "message": "Task status updated successfully." }


    def create_task(
        self,
        task_id: str,
        description: str,
        status: str,
        due_date: Optional[float] = None,
        priority: str = "medium",
        assigned_to: Optional[str] = None,
    ) -> dict:
        """
        Add a new task with a unique task_id, description, and initial status.

        Args:
            task_id (str): Unique identifier for the task.
            description (str): Description of the task.
            status (str): Initial status; must be one of "pending", "in progress", "completed", "blocked".
            due_date (Optional[float]): Unix timestamp for task deadline (default: None).
            priority (str): Priority level (e.g., "low", "medium", "high") (default: "medium").
            assigned_to (Optional[str]): ID of the user to whom the task is assigned (default: None).

        Returns:
            dict: {
                "success": bool,
                "message": str,  # On success: confirmation; on failure: error key with reason
            }

        Constraints:
            - task_id must be unique.
            - status must be one of: "pending", "in progress", "completed", "blocked".
            - If assigned_to is provided, it must refer to an existing user.
            - created_at is set automatically to current time; completed_at is None by default.
        """
        # Check if task_id already exists
        if task_id in self.tasks:
            return {"success": False, "error": "Task ID already exists"}

        # Validate status
        valid_statuses = ["pending", "in progress", "completed", "blocked"]
        if status not in valid_statuses:
            return {"success": False, "error": f"Invalid status: {status}. Must be one of {valid_statuses}"}

        # If assigned_to is provided, check if user exists
        if assigned_to is not None and assigned_to not in self.users:
            return {"success": False, "error": f"User with ID '{assigned_to}' does not exist"}

        # Set timestamps
        created_at = time.time()  # Current Unix timestamp
        completed_at = None
        if status == "completed":
            completed_at = created_at  # Automatically set if status is completed

        # Create new task
        new_task: TaskInfo = {
            "task_id": task_id,
            "description": description,
            "status": status,
            "created_at": created_at,
            "completed_at": completed_at,
            "due_date": due_date,
            "priority": priority,
            "assigned_to": assigned_to,
        }

        # Add to tasks
        self.tasks[task_id] = new_task

        return {"success": True, "message": "Task created successfully"}

    def assign_task_to_user(self, task_id: str, user_id: str) -> dict:
        """
        Assign a task to a user by updating the assigned_to field.

        Args:
            task_id (str): The unique identifier of the task.
            user_id (str): The unique identifier of the user to whom the task will be assigned.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success: descriptive message
            }
            or
            {
                "success": False,
                "error": str  # "Task not found" or "User not found"
            }

        Constraints:
            - The task must exist in the system.
            - The user must exist in the system.
            - There are no restrictions on reassignment (can reassign from one user to another).
        """
        if task_id not in self.tasks:
            return { "success": False, "error": "Task not found" }

        if user_id not in self.users:
            return { "success": False, "error": "User not found" }

        self.tasks[task_id]["assigned_to"] = user_id

        return {
            "success": True,
            "message": f"Task '{task_id}' assigned to user '{user_id}'."
        }

    def update_task_due_date(self, task_id: str, due_date: Optional[float]) -> dict:
        """
        Modify the due date of an existing task.

        Args:
            task_id (str): The unique identifier of the task to update.
            due_date (Optional[float]): The new due date as a Unix timestamp. 
                                       Use None to remove the due date.

        Returns:
            dict: {
                "success": True,
                "message": "Task due date updated successfully."
            }
            or
            {
                "success": False,
                "error": str  # e.g., "Task not found"
            }

        Constraints:
            - The task must exist in the system.
            - No restriction on the value of due_date (can be past, future, or None).
        """
        if task_id not in self.tasks:
            return { "success": False, "error": "Task not found" }

        self.tasks[task_id]["due_date"] = due_date
        return { "success": True, "message": "Task due date updated successfully." }

    def update_task_priority(self, task_id: str, new_priority: str) -> dict:
        """
        Change the priority level of a task.

        Args:
            task_id (str): The unique identifier of the task to update.
            new_priority (str): The new priority value to assign to the task.

        Returns:
            dict: {
                "success": True,
                "message": "Task priority updated successfully."
            }
            or
            {
                "success": False,
                "error": "Task not found"
            }

        Constraints:
            - The task must exist in the system.
            - No restrictions on priority values are enforced (any string is allowed).
        """
        if task_id not in self.tasks:
            return {"success": False, "error": "Task not found"}

        self.tasks[task_id]["priority"] = new_priority
        return {"success": True, "message": "Task priority updated successfully."}

    def add_task_to_project(self, task_id: str, project_id: str) -> dict:
        """
        Add an existing task to a project by linking its task_id to the project's tasks list.

        Args:
            task_id (str): The ID of the task to add.
            project_id (str): The ID of the project to add the task to.

        Returns:
            dict: {
                "success": True,
                "message": "Task added to project successfully."
            }
            or
            {
                "success": False,
                "error": str  # Description of error: task or project not found
            }

        Constraints:
            - The task_id must refer to an existing task.
            - The project_id must refer to an existing project.
            - Idempotent: adding an already-present task is allowed and treated as success.
        """
        if project_id not in self.projects:
            return { "success": False, "error": f"Project with ID '{project_id}' does not exist." }

        if task_id not in self.tasks:
            return { "success": False, "error": f"Task with ID '{task_id}' does not exist." }

        project = self.projects[project_id]

        if task_id not in project["tasks"]:
            project["tasks"].append(task_id)

        return { "success": True, "message": "Task added to project successfully." }

    def remove_task_from_project(self, project_id: str, task_id: str) -> dict:
        """
        Remove a task from a project's list of associated tasks.

        Args:
            project_id (str): The ID of the project.
            task_id (str): The ID of the task to remove.

        Returns:
            dict: {
                "success": True,
                "message": "Task removed from project successfully."
            }
            or
            {
                "success": False,
                "error": str  # Description of the error (e.g., project or task not found)
            }

        Constraints:
            - The project_id must exist in the system.
            - The task_id must exist in the system.
            - If the task is not in the project, the operation is still considered successful.
        """
        if project_id not in self.projects:
            return { "success": False, "error": "Project not found" }

        if task_id not in self.tasks:
            return { "success": False, "error": "Task not found" }

        project = self.projects[project_id]

        # Remove task_id from the project's tasks list if present
        if task_id in project["tasks"]:
            project["tasks"].remove(task_id)

        return { "success": True, "message": "Task removed from project successfully." }


    def bulk_complete_tasks(self, task_ids: List[str]) -> Dict:
        """
        Mark multiple tasks as completed in a single operation, with individual validation.

        Args:
            task_ids (List[str]): List of task IDs to attempt to complete.

        Returns:
            dict: {
                "success": True,
                "message": str,
                "details": {
                    "succeeded": List[str],  # List of task_ids successfully completed
                    "failed": List[Dict]     # List of dicts with 'task_id' and 'reason' for failures
                }
            }
            or
            {
                "success": False,
                "error": str  # Only if critical issue (e.g., invalid input type)
            }

        Constraints:
            - A task can only be marked as "completed" if it is not already "completed".
            - The completed_at timestamp is set when a task is completed.
            - The status must be one of: "pending", "in progress", "completed", "blocked".
            - Only existing tasks are processed.
        """
        if not isinstance(task_ids, list):
            return { "success": False, "error": "task_ids must be a list" }

        allowed_statuses = ["pending", "in progress", "blocked", "completed"]

        current_time = time.time()
        succeeded = []
        failed = []

        for task_id in task_ids:
            if task_id not in self.tasks:
                failed.append({
                    "task_id": task_id,
                    "reason": "Task does not exist"
                })
                continue

            task = self.tasks[task_id]

            if task["status"] not in allowed_statuses:
                failed.append({
                    "task_id": task_id,
                    "reason": f"Invalid status: {task['status']}"
                })
                continue

            if task["status"] == "completed":
                failed.append({
                    "task_id": task_id,
                    "reason": "Task is already completed"
                })
                continue

            # Update task status and completion timestamp
            task["status"] = "completed"
            task["completed_at"] = current_time
            self.tasks[task_id] = task  # Ensure update is persisted (redundant if mutable, but safe)

            succeeded.append(task_id)

        # Return success=True even if some failed — bulk operations allow partial success
        return {
            "success": True,
            "message": f"Bulk completion processed: {len(succeeded)} succeeded, {len(failed)} failed.",
            "details": {
                "succeeded": succeeded,
                "failed": failed
            }
        }

