def list_tasks_by_user(self, user_id: str) -> dict:
    """
    Retrieve all tasks assigned to a specific user.

    Args:
        user_id (str): The unique identifier of the user.

    Returns:
        dict: {
            "success": True,
            "data": List[TaskInfo]  # List of tasks assigned to the user (may be empty)
        }
        or
        {
            "success": False,
            "error": str  # Description of the error, e.g. "User does not exist"
        }

    Constraints:
        - The user_id must correspond to an existing user.
        - Only tasks where 'assigned_to' matches the user_id are returned.
    """
    if user_id not in self.users:
        return {"success": False, "error": "User does not exist"}

    assigned_tasks = [
