def update_task_status(self, task_id: str, new_status: str) -> Dict[str, object]:
    """
    Change the status of a task to a valid value.

    Args:
        task_id (str): The unique ID of the task to update.
        new_status (str): The new status to set. Must be one of:
                         "pending", "in progress", "completed", "blocked".

    Returns:
        dict: {
            "success": bool,
            "message": str  # On success
        }
        or
        {
            "success": False,
            "error": str  # On failure
        }

    Constraints:
        - Task must exist.
        - New status must be one of the allowed values.
        - A task already marked "completed" cannot be completed again.
        - If status is set to "completed", the completed_at timestamp is set to current time.
    """
    # Check if task exists
    if task_id not in self.tasks:
        return { "success": False, "error": f"Task with ID '{task_id}' not found." }

    allowed_statuses = ["pending", "in progress", "completed", "blocked"]
    if new_status not in allowed_statuses:
        return {
            "success": False,
            "error": f"Invalid status '{new_status}'. Must be one of {allowed_statuses}."
        }

    task = self.tasks[task_id]

    # Prevent re-completing a completed task
    if new_status == "completed":
        if task["status"] == "completed":
            return {
                "success": False,
                "error": "Task is already completed and cannot be completed again."
            }
        # Set completed_at timestamp
        task["completed_at"] = time.time()

    # Update the status
    task["status"] = new_status

    return { "success": True, "message": "Task status updated successfully." }

