def add_task_to_project(self, task_id: str, project_id: str) -> dict:
    """
    Add an existing task to a project by linking its task_id to the project's tasks list.

    Args:
        task_id (str): The ID of the task to add.
        project_id (str): The ID of the project to add the task to.

    Returns:
        dict: {
            "success": True,
            "message": "Task added to project successfully."
        }
        or
        {
            "success": False,
            "error": str  # Description of error: task or project not found
        }

    Constraints:
        - The task_id must refer to an existing task.
        - The project_id must refer to an existing project.
        - Idempotent: adding an already-present task is allowed and treated as success.
    """
    if project_id not in self.projects:
        return { "success": False, "error": f"Project with ID '{project_id}' does not exist." }

    if task_id not in self.tasks:
        return { "success": False, "error": f"Task with ID '{task_id}' does not exist." }

    project = self.projects[project_id]

    if task_id not in project["tasks"]:
        project["tasks"].append(task_id)

    return { "success": True, "message": "Task added to project successfully." }

