def bulk_complete_tasks(self, task_ids: List[str]) -> Dict:
    """
    Mark multiple tasks as completed in a single operation, with individual validation.

    Args:
        task_ids (List[str]): List of task IDs to attempt to complete.

    Returns:
        dict: {
            "success": True,
            "message": str,
            "details": {
                "succeeded": List[str],  # List of task_ids successfully completed
                "failed": List[Dict]     # List of dicts with 'task_id' and 'reason' for failures
            }
        }
        or
        {
            "success": False,
            "error": str  # Only if critical issue (e.g., invalid input type)
        }

    Constraints:
        - A task can only be marked as "completed" if it is not already "completed".
        - The completed_at timestamp is set when a task is completed.
        - The status must be one of: "pending", "in progress", "completed", "blocked".
        - Only existing tasks are processed.
    """
    if not isinstance(task_ids, list):
        return { "success": False, "error": "task_ids must be a list" }

    allowed_statuses = ["pending", "in progress", "blocked", "completed"]

    current_time = time.time()
    succeeded = []
    failed = []

    for task_id in task_ids:
        if task_id not in self.tasks:
            failed.append({
                "task_id": task_id,
                "reason": "Task does not exist"
            })
            continue

        task = self.tasks[task_id]

        if task["status"] not in allowed_statuses:
            failed.append({
                "task_id": task_id,
                "reason": f"Invalid status: {task['status']}"
            })
            continue

        if task["status"] == "completed":
            failed.append({
                "task_id": task_id,
                "reason": "Task is already completed"
            })
            continue

        # Update task status and completion timestamp
        task["status"] = "completed"
        task["completed_at"] = current_time
        self.tasks[task_id] = task  # Ensure update is persisted (redundant if mutable, but safe)

        succeeded.append(task_id)

    # Return success=True even if some failed — bulk operations allow partial success
    return {
        "success": True,
        "message": f"Bulk completion processed: {len(succeeded)} succeeded, {len(failed)} failed.",
        "details": {
            "succeeded": succeeded,
            "failed": failed
        }
    }

